  const source=d=>{if(recovered(d))return t('Aside 복구 요약','Recovered Aside summaries');if(PLAIN[d.id])return t(PLAIN[d.id][0],PLAIN[d.id][1]);const s=String(d.source || '')+' '+d.id;if(/aside/i.test(s))return t('Aside 로컬 기록','Aside local records');if(d.scope==='account')return t('계정 서버','Account server');if(/cli|claude|codex|grok|antigravity/i.test(s))return t('이 PC의 CLI 기록','Local CLI records');return t('이 PC의 기록','Local records');};
