  const APP_LABELS={aside:['Aside','Aside'],grok_cli:['Grok CLI','Grok CLI'],antigravity_cli:['Antigravity CLI','Antigravity CLI'],claude_vscode:['Claude Code (VS Code 확장)','Claude Code (VS Code extension)'],claude_cli:['Claude Code (터미널)','Claude Code (terminal)'],claude_desktop:['Claude 데스크톱','Claude desktop'],claude_sdk_cli:['Claude Code (프로그램이 실행)','Claude Code (run by a program)'],claude_sdk_ts:['Claude SDK (TypeScript)','Claude SDK (TypeScript)'],claude_sdk_py:['Claude SDK (Python)','Claude SDK (Python)'],codex_exec:['Codex exec (프로그램이 실행)','Codex exec (run by a program)'],codex_vscode:['Codex (VS Code 확장)','Codex (VS Code extension)'],codex_desktop:['Codex 데스크톱','Codex desktop'],codex_cli:['Codex CLI','Codex CLI'],codex_in_claude_code:['Claude Code에서 실행한 Codex','Codex run from Claude Code']};
