  const ISSUES={accounts_not_separable:()=>t('이 PC 기록에는 계정 정보가 없어요. 이 PC에 로그인했던 모든 계정의 사용량이 함께 들어 있고, 계정별로 나눌 수 없어요.','Local logs carry no account. Usage from every account signed in on this PC is mixed together and cannot be split by account.'),aside_session_files_missing:()=>t('일부 Aside 세션의 원본 메시지 파일이 없어요. 남아 있는 턴 통계는 Aside 복구 요약에서 따로 볼 수 있어요.','Some Aside message files are missing. Remaining turn counters appear separately under Recovered Aside summaries.'),server_day_timezone_unverified:()=>t('계정의 일별 날짜는 서버가 제공한 그대로예요. 서버가 날짜를 나누는 시간대는 확인하지 못했어요.','Account dates are shown as supplied by the server. Its daily timezone is not verified.'),capture_time_from_saved_probe:()=>t('계정 기록의 확인 시각은 조회 결과를 파일로 저장한 시각이에요.','The account capture time is when the query result was saved to a file.'),count_components_unavailable:()=>t('전체 토큰의 세부 구성은 제공되지 않아요. 없는 항목은 0으로 표시하지 않아요.','The total-token breakdown is unavailable. Missing components are not shown as zero.'),cache_semantics_not_billing_verified:()=>t('캐시 읽기는 따로 보여요. 입력과 출력만 더한 합계이며 요금 산정 방식은 검증하지 못했어요.','Cache reads are shown separately. The total adds input and output only; billing semantics are not verified.'),other_apps_not_included:()=>t('이 출처에는 Aside에서 기록한 사용량만 들어 있어요. 다른 앱의 기록과 자동으로 더하지 않아요.','This source contains only usage recorded by Aside. It is not automatically combined with other apps.'),record_unit_is_turn:()=>t('기록 수는 개별 모델 호출이 아니라 저장된 턴 요약의 개수예요.','Record counts refer to saved turn summaries, not individual model calls.'),model_attribution_unavailable:()=>t('당시 모델은 기록에 없어서 모델별로 나눌 수 없어요.','The model was not recorded, so a model breakdown is unavailable.'),turn_end_date_not_event_time:()=>t('턴 종료일 우선: 종료 시각이 없으면 마지막 메시지나 시작 시각으로 묶었어요. 정확한 토큰 발생 시각이 아니라서 시간대별 분석은 제공하지 않아요.','Turn end date is preferred, falling back to the last message or start time. These are not exact token-event times, so no hourly analysis is provided.'),cross_source_overlap_unverified:()=>t('다른 출처와 겹치는지 확인하지 못했어요. 합산하면 같은 사용량을 두 번 셀 수 있어요.','Overlap with other sources is unverified. Combining them may count the same usage twice.'),missing_aside_session_files:()=>t('일부 Aside 세션 파일을 찾지 못했어요. 그 세션의 사용량은 빠져 있을 수 있어요.','Some Aside session files were not found, so usage from those sessions may be missing.'),unmetered_records:()=>t('토큰 수치가 없는 기록이 있어요. 합계에 넣지 않았고 0으로 보지도 않아요.','Some records have no token counts. They are left out of totals and are not treated as zero.')};
  const RECOVERED_CODES=['model_attribution_unavailable','turn_end_date_not_event_time','cross_source_overlap_unverified'];
  function issueCodes(d){const c=d.coverage||{},raw=[...(c.issues||[]),...(d.semantics?.warnings||[])].map(x=>typeof x==='string'?x:x?.code).filter(v=>typeof v==='string'&&v);if(recovered(d))raw.push(...RECOVERED_CODES);if(C.number(c.unmeteredRecords)&&c.unmeteredRecords>0)raw.push('unmetered_records');return [...new Set(raw)];}
