  function colRole(k,d){const s=d.semantics||{},r=String(s.totalRule||'');if(k==='reasoning')return s.outputIncludesReasoning===true?t('출력에 포함, 다시 더하지 않음','In output, not added again'):s.outputIncludesReasoning===false?t('출력과 별도 항목','Separate from output'):t('출력 포함 여부 미확인','Inclusion in output unknown');if(r==='reported_total')return t('구성 미제공','Components unavailable');if(!r)return t('합계 포함 여부 미확인','Total inclusion unknown');const key={input:'input',cacheRead:'cache_read',cacheCreate:'cache_create',output:'output'}[k];if(k==='cacheRead'&&!r.includes(key)&&s.inputIncludesCache===true)return t('입력에 포함','In input');return r.includes(key)?t('합계에 포함','In total'):t('합계에 미포함','Not in total');}
  let chartPicked=null;
  function hideChartTip(){const tip=$('#chart-tooltip');if(tip)tip.hidden=true;document.querySelectorAll?.('[aria-describedby="chart-tooltip"]').forEach(g=>g.removeAttribute?.('aria-describedby'));}
  function showChartTip(el){const tip=$('#chart-tooltip'),area=$('.chart-area');if(!tip||!area?.getBoundingClientRect||!el?.getBoundingClientRect)return;tip.textContent=(el.dataset.display||el.dataset.readout||'').replaceAll(' / ','\n');tip.hidden=false;const a=area.getBoundingClientRect(),r=(el.querySelector?.('.bar-value')||el.querySelector?.('.bar')||el).getBoundingClientRect();tip.style.left=Math.max(4,Math.min(area.clientWidth-tip.offsetWidth-4,r.left-a.left+r.width/2-tip.offsetWidth/2))+'px';tip.style.top=Math.max(0,r.top-a.top-tip.offsetHeight-8)+'px';document.querySelectorAll?.('[aria-describedby="chart-tooltip"]').forEach(g=>g.removeAttribute?.('aria-describedby'));el.setAttribute?.('aria-describedby','chart-tooltip');}
