  function bucketReadout(r){if(!r)return '';const label=r.date.length===7?new Intl.DateTimeFormat(locale(),{year:'numeric',month:'long',timeZone:'UTC'}).format(new Date(r.date+'-01T00:00:00Z')):dshort(r.date);return label+' / '+(C.number(r.tokens)?exact(r.tokens)+' '+t('토큰','tokens')+(r.coverageStatus==='partial'?' / '+t('일부 기록','Partial'):''):t('기록 없음, 사용량 미확인','No record, usage unknown'));}
