  const winLabel=l=>/^(5h|five_hour|five_hours)$/i.test(l.window)?t('5시간','5 hours'):/^(7d|weekly|seven_day)$/i.test(l.window)?t('주간','Weekly'):/daily|24h/i.test(l.window)?t('일간','Daily'):/monthly|30d/i.test(l.window)?t('월간','Monthly'):t('한도 구간','Limit window');
